CREATE TABLE meetings (
        id SERIAL PRIMARY KEY,
        project_id INTEGER NOT NULL,
        meeting_date TEXT NOT NULL,
        title TEXT NOT NULL,
        meeting_type TEXT NOT NULL
    );
CREATE TABLE ncrs (
        id SERIAL PRIMARY KEY,
        project_id INTEGER NOT NULL,
        supplier_id INTEGER,
        subcontractor_id INTEGER,
        ncr_type TEXT NOT NULL,
        description TEXT NOT NULL,
        root_cause TEXT NOT NULL,
        issue_date TEXT NOT NULL,
        status TEXT NOT NULL
    );
CREATE TABLE project_decisions (
        id SERIAL PRIMARY KEY,
        project_id INTEGER NOT NULL,
        meeting_id INTEGER NOT NULL,
        decision_date TEXT NOT NULL,
        decision_text TEXT NOT NULL,
        owner TEXT NOT NULL
    );
CREATE TABLE projects (
        id SERIAL PRIMARY KEY,
        project_code TEXT NOT NULL,
        project_name TEXT NOT NULL,
        project_type TEXT NOT NULL,
        client_name TEXT NOT NULL,
        city TEXT NOT NULL,
        start_date TEXT NOT NULL,
        planned_finish TEXT NOT NULL,
        actual_finish TEXT,
        status TEXT NOT NULL,
        budget DOUBLE PRECISION NOT NULL
    );
CREATE TABLE purchase_orders (
        id SERIAL PRIMARY KEY,
        pr_id INTEGER NOT NULL,
        project_id INTEGER NOT NULL,
        supplier_id INTEGER NOT NULL,
        po_number TEXT NOT NULL,
        issue_date TEXT NOT NULL,
        promised_delivery TEXT NOT NULL,
        actual_delivery TEXT,
        status TEXT NOT NULL,
        is_late INTEGER NOT NULL,
        delay_days INTEGER NOT NULL,
        delay_root_cause TEXT
    );
CREATE TABLE purchase_requests (
        id SERIAL PRIMARY KEY,
        project_id INTEGER NOT NULL,
        request_no TEXT NOT NULL,
        material_category TEXT,
        specification TEXT,
        required_delivery_date TEXT,
        status TEXT NOT NULL,
        rework_reason TEXT,
        created_at TEXT NOT NULL
    );
CREATE TABLE safety_events (
        id SERIAL PRIMARY KEY,
        project_id INTEGER NOT NULL,
        subcontractor_id INTEGER NOT NULL,
        event_date TEXT NOT NULL,
        severity TEXT NOT NULL,
        description TEXT NOT NULL,
        corrective_action TEXT NOT NULL
    );
CREATE TABLE site_reports (
        id SERIAL PRIMARY KEY,
        project_id INTEGER NOT NULL,
        report_date TEXT NOT NULL,
        weather TEXT NOT NULL,
        summary TEXT NOT NULL
    );
CREATE TABLE subcontractor_evaluations (
        id SERIAL PRIMARY KEY,
        subcontractor_id INTEGER NOT NULL,
        project_id INTEGER NOT NULL,
        evaluation_date TEXT NOT NULL,
        quality_score INTEGER NOT NULL,
        safety_score INTEGER NOT NULL,
        schedule_score INTEGER NOT NULL,
        manpower_score INTEGER NOT NULL,
        overall_rating DOUBLE PRECISION NOT NULL,
        comments TEXT NOT NULL,
        linked_safety_event_id INTEGER,
        linked_ncr_id INTEGER,
        linked_daily_activity_id INTEGER
    );
CREATE TABLE subcontractors (
        id SERIAL PRIMARY KEY,
        name TEXT NOT NULL,
        trade TEXT NOT NULL,
        contact_person TEXT NOT NULL,
        phone TEXT NOT NULL,
        email TEXT NOT NULL,
        classification TEXT NOT NULL,
        city TEXT NOT NULL,
        status TEXT NOT NULL,
        created_at TEXT NOT NULL
    );
CREATE TABLE suppliers (
        id SERIAL PRIMARY KEY,
        supplier_name TEXT NOT NULL,
        category TEXT NOT NULL,
        city TEXT NOT NULL,
        status TEXT NOT NULL
    );
